from datetime import datetime

# n8n 输入
data = items[0]["json"]["data"]
cur_jira_key = items[0]["json"]["key"]

# jira_source 优先级
SOURCE_ORDER = {
    "test_item": 0,
    "test_case": 1,
    "test_module": 2,
}

def parse_time(t):
    """
    解析时间格式：
    2026-01-20T19:16:39.000+0800
    """
    return datetime.strptime(t, "%Y-%m-%dT%H:%M:%S.%f%z")

# ---------------- 1️⃣ 按 jira_key 去重（保留最新） ----------------
latest_by_key = {}
count = 0
for item in data:
    key = item.get("jira_key")
    if not key:
      continue
    t = parse_time(item.get("created_time"))

    if key and key != cur_jira_key:
      if key not in latest_by_key and key:
          latest_by_key[key] = item
      else:
          old_time = parse_time(latest_by_key[key]["created_time"])
          if t > old_time:
              latest_by_key[key] = item

deduped_data = list(latest_by_key.values())

# ---------------- 2️⃣ 排序 ----------------
data_sorted = sorted(
    deduped_data,
    key=lambda x: (
        SOURCE_ORDER.get(x.get("jira_source"), 99),
        -parse_time(x.get("created_time")).timestamp()
    )
)

count = len(data_sorted)
if count == 0:
  return [{
    "json": {
        "data": "没有找到相似的jira",
        "count": count
    }
  }]
return [{
    "json": {
        "data": data_sorted[:5],
        "count": count
    }
}]

