import re

result = []

# 删除以下类型内容：
# !image-xxx.png!
# !screenshot-xxx.png!
# !screenshot-xxx.png|thumbnail!
# [~username]  (username 任意)
pattern = re.compile(
    r'!(?:image|screenshot)-[\w\-]+\.png(?:\|thumbnail)?!|\[~[^\]]+\]'
)

exclude_keywords = ["详细信息请参见链接","Change merged", "Change proposed"]

for item in items:
    comments = item.get("json", {}).get("comments", [])

    for comment in comments:
        # 跳过包含排除关键词的评论
        if any(keyword in comment for keyword in exclude_keywords):
            continue

        # 删除匹配内容，并合并多余空格
        cleaned = re.sub(pattern, '', comment)
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()

        if cleaned:
            result.append(cleaned)

return [{
    "json": {
        "comments": result
    }
}]

from difflib import SequenceMatcher

SIMILARITY_THRESHOLD = 0.85

def is_similar(a, b):
    return SequenceMatcher(None, a, b).ratio() >= SIMILARITY_THRESHOLD


items = _input.all()
result = ""
for item in items:
    comments = item.json.get("comments", [])
    deduped = []

    for c in comments:
        is_dup = False
        for d in deduped:
            if is_similar(c, d):
                is_dup = True
                break

        if not is_dup:
            deduped.append(c)

    item.json["comments"] = deduped
result = "\n".join(item.json["comments"])

return {"comments_list": item.json["comments"],
       "comment_conbine": result}

import re
import json

MAX_COMMENT_LEN = 2000
BASE64_THRESHOLD = 200

KEYWORDS = (
    'error', 'Error', 'failed', 'Fail',
    'exception', 'panic',
    "Can't", 'cannot',
    'invalid', 'format'
)


def has_long_base64(text: str) -> bool:
    pattern = rf'[A-Za-z0-9+/=]{{{BASE64_THRESHOLD},}}'
    return bool(re.search(pattern, text))


def json_ratio(text: str) -> float:
    """
    Roughly detect JSON / structured noise ratio
    """
    if not text:
        return 0.0
    json_chars = sum(text.count(c) for c in '{}[]":,')
    return json_chars / len(text)


def extract_key_info(text: str) -> str:
    lines = (l.strip() for l in text.splitlines())
    hits = [l for l in lines if any(k in l for k in KEYWORDS)]
    return '\n'.join(hits)


def should_drop_comment(raw: str) -> bool:
    """
    Strong drop rules
    """
    # 极端长度
    if len(raw) > 8000:
        return True

    # csr + base64 = 直接丢弃
    if '"csr"' in raw and has_long_base64(raw):
        return True

    # JSON 噪音占比过高
    if json_ratio(raw) > 0.6:
        return True

    return False


def filter_comments(comments: list[str]) -> list[str]:
    """
    Input : raw comments list
    Output: cleaned & meaningful comments
    """
    results = []

    for raw in comments:
        if not raw or not raw.strip():
            continue
        text = raw
        # 第一层强过滤
        if should_drop_comment(raw):
            # 第二层：提取有意义内容
            summary = extract_key_info(raw)
            if not summary:
                continue
            else:
                text = summary
        # 最终截断
        if len(text) > MAX_COMMENT_LEN:
            text = text[:MAX_COMMENT_LEN] + '\n[TRUNCATED]'

        results.append(text)

    return results
filtered = []
for item in items:
    comments = item.get("json", {}).get("comments", [])
    filtered = filter_comments(comments)

return {'comments': filtered}

