table_pattern = re.compile(
    r"([^\s#]+)#([^\s\",|]+)"
)
failed_tests = []
# desc
for text in test_fails:
  for m in table_pattern.finditer(text):
      failed_tests.append((m.group(1).strip(), m.group(2).strip()))


if not failed_tests:
    table_pattern = re.compile(
        r"(\btest[^\s\"|]+\b)"
    )

    # desc
    for text in test_fails:
      for m in table_pattern.finditer(text):
          failed_tests.append((None, m.group(1).strip()))

if not failed_tests: 
    for text in test_fails:
      for m in table_pattern.finditer(text):
          failed_tests.append((test_fails, None))

# 去重
failed_tests_unique = []
seen = set()
for tc, ti in failed_tests:
    key = f"{tc}#{ti}"
    if key not in seen:
        seen.add(key)
        failed_tests_unique.append({
            "test_case": tc,
            "test_item": ti
        })


return {"failed_tests" : failed_tests_unique, "failed_count": len(failed_tests_unique)}

